codeExamples.code:
CREATE NONCLUSTERED INDEX IX_Tickets_tenant_status_created
    ON Tickets (tenant_id, status, created_at);

-- USES the index (leftmost prefix tenant_id):
SELECT * FROM Tickets WHERE tenant_id = 7;

-- USES the index (prefix tenant_id + status):
SELECT * FROM Tickets WHERE tenant_id = 7 AND status = ''open'';

-- USES the index fully (equality, equality, then range on created_at):
SELECT * FROM Tickets
WHERE tenant_id = 7 AND status = ''open''
  AND created_at >= ''2026-01-01'';

-- CANNOT seek (leading column tenant_id omitted -> not a prefix):
SELECT * FROM Tickets WHERE status = ''open'';

-- PARTIALLY uses it (seeks tenant_id, but created_at filter is not
-- a usable prefix because status is skipped):
SELECT * FROM Tickets WHERE tenant_id = 7 AND created_at >= ''2026-01-01'';
